const d = $input.first().json;
// n8n errorTrigger payload shape:
//   d.execution.error.message / .node.name / .node.type
//   d.execution.id, d.workflow.id, d.workflow.name
const err     = d?.execution?.error || {};
const nodeName = err?.node?.name || err?.nodeName || 'Unknown Node';
const msg      = (err?.message || err?.description || JSON.stringify(err)).substring(0, 400);
const ts       = new Date().toLocaleString('en-IN', { timeZone: 'Asia/Kolkata' });
const wfId     = d?.workflow?.id || '298f3JSOE72nhW59';
const execId   = d?.execution?.id || '';
const url      = execId
  ? `https://divyesh-sharma.app.n8n.cloud/workflow/${wfId}/executions/${execId}`
  : `https://divyesh-sharma.app.n8n.cloud/workflow/${wfId}/executions`;

const text = `🚨 *EL Node Failed*\n\n❌ *Node:* ${nodeName}\n📋 *Error:* ${msg}\n🕐 *Time (IST):* ${ts}\n🔗 [View Execution](${url})`;
return [{ json: { text } }];
